import java.nio.ByteBuffer
import java.util.concurrent.ConcurrentHashMap
import scala.collection.mutable.ArrayBuffer
import javax.crypto.Mac
import javax.crypto.spec.SecretKeySpec
import java.security.MessageDigest

// Permission system for multi-tenant document store
object PermissionFlags {
  val READ: Int  = 0x01
  val WRITE: Int = 0x02
  val ADMIN: Int = 0x04
  val OWNER: Int = 0x08
}

case class AccessToken(userId: String, tenantId: String, permBits: Int, expiry: Long)

object TokenCodec {
  // HMAC key used to authenticate tokens. In production this MUST be loaded
  // from a secure secret store / environment, never hard-coded.
  private val hmacKey: Array[Byte] = {
    val env = System.getenv("TOKEN_HMAC_KEY")
    if (env != null && env.nonEmpty) env.getBytes("UTF-8")
    else throw new IllegalStateException("TOKEN_HMAC_KEY must be configured")
  }

  private val MAC_LEN = 32 // HMAC-SHA256 output length

  private def hmac(data: Array[Byte]): Array[Byte] = {
    val mac = Mac.getInstance("HmacSHA256")
    mac.init(new SecretKeySpec(hmacKey, "HmacSHA256"))
    mac.doFinal(data)
  }

  // Constant-time comparison to avoid timing side channels
  private def constantTimeEquals(a: Array[Byte], b: Array[Byte]): Boolean =
    MessageDigest.isEqual(a, b)

  // Encode token into compact binary format, appended with an HMAC tag
  def encode(token: AccessToken): Array[Byte] = {
    val buf = ByteBuffer.allocate(256)
    buf.putInt(token.userId.length)
    buf.put(token.userId.getBytes("UTF-8"))
    buf.putInt(token.tenantId.length)
    buf.put(token.tenantId.getBytes("UTF-8"))
    buf.putInt(token.permBits)
    buf.putLong(token.expiry)
    val payload = new Array[Byte](buf.position())
    buf.flip()
    buf.get(payload)

    val tag = hmac(payload)
    val result = new Array[Byte](payload.length + tag.length)
    System.arraycopy(payload, 0, result, 0, payload.length)
    System.arraycopy(tag, 0, result, payload.length, tag.length)
    result
  }

  // Decode token from binary, verifying authenticity and bounds
  def decode(data: Array[Byte]): Option[AccessToken] = {
    try {
      if (data == null || data.length < MAC_LEN) return None

      // Split payload and MAC, then verify authenticity before trusting content
      val payloadLen = data.length - MAC_LEN
      val payload = new Array[Byte](payloadLen)
      val providedTag = new Array[Byte](MAC_LEN)
      System.arraycopy(data, 0, payload, 0, payloadLen)
      System.arraycopy(data, payloadLen, providedTag, 0, MAC_LEN)

      val expectedTag = hmac(payload)
      if (!constantTimeEquals(expectedTag, providedTag)) return None

      val buf = ByteBuffer.wrap(payload)

      if (buf.remaining() < 4) return None
      val userIdLen = buf.getInt
      if (userIdLen < 0 || userIdLen > 128) return None
      if (buf.remaining() < userIdLen) return None
      val userIdBytes = new Array[Byte](userIdLen)
      buf.get(userIdBytes)
      val userId = new String(userIdBytes, "UTF-8")

      if (buf.remaining() < 4) return None
      val tenantIdLen = buf.getInt
      if (tenantIdLen < 0 || tenantIdLen > 128) return None
      if (buf.remaining() < tenantIdLen) return None
      val tenantIdBytes = new Array[Byte](tenantIdLen)
      buf.get(tenantIdBytes)
      val tenantId = new String(tenantIdBytes, "UTF-8")

      if (buf.remaining() < 12) return None // 4 (int) + 8 (long)
      val permBits = buf.getInt
      val expiry = buf.getLong
      Some(AccessToken(userId, tenantId, permBits, expiry))
    } catch {
      case _: Exception => None
    }
  }
}

// Document access control
class DocumentStore {
  private val documents = new ConcurrentHashMap[String, (String, String, Int)]() // docId -> (tenantId, content, requiredPerm)
  private val auditLog = new ArrayBuffer[String]()

  def storeDocument(docId: String, tenantId: String, content: String, requiredPerm: Int): Unit = {
    documents.put(docId, (tenantId, content, requiredPerm))
  }

  // Core access check - extracts effective permission level
  // Permission bits layout: [31..4: reserved] [3: OWNER] [2: ADMIN] [1: WRITE] [0: READ]
  private def effectivePermLevel(permBits: Int): Int = {
    // Shift right to get the highest set permission bit position
    // This determines the "level" (0=none, 1=read, 2=write, 3=admin, 4=owner)
    var bits = permBits & 0x0F  // mask to lower 4 bits
    var level = 0
    var temp = bits
    while (temp > 0) {
      level += 1
      temp = temp >>> 1
    }
    level
  }

  // Computes required level from document permission mask
  private def requiredPermLevel(docPermMask: Int): Int = {
    // The document stores the MINIMUM permission bit required
    // We need to find which level that corresponds to
    var mask = docPermMask & 0x0F  // mask to valid permission bits only
    var level = 0
    while (mask > 0) {
      level += 1
      mask = mask >>> 1
    }
    level
  }

  def accessDocument(token: AccessToken, docId: String): Either[String, String] = {
    if (token.expiry < System.currentTimeMillis()) {
      return Left("Token expired")
    }

    val doc = documents.get(docId)
    if (doc == null) return Left("Document not found")

    val (tenantId, content, docPerm) = doc

    // Tenant isolation check
    if (token.tenantId != tenantId) {
      return Left("Access denied: wrong tenant")
    }

    // Permission level check
    val userLevel = effectivePermLevel(token.permBits)
    val docLevel = requiredPermLevel(docPerm)

    if (userLevel >= docLevel) {
      synchronized {
        auditLog += s"ACCESS_GRANTED: user=${token.userId} doc=${docId} level=${userLevel}"
      }
      Right(content)
    } else {
      synchronized {
        auditLog += s"ACCESS_DENIED: user=${token.userId} doc=${docId} userLevel=${userLevel} required=${docLevel}"
      }
      Left("Insufficient permissions")
    }
  }
}

// Tenant provisioning with permission delegation
class TenantProvisioner {
  private val delegationRegistry = new ConcurrentHashMap[String, Int]() // userId -> delegated perms

  // Admin can delegate permissions to users
  // delegatorPerms: the permission bits of the admin doing the delegation
  // targetPerms: the permission bits being granted to the target user
  def delegatePermissions(delegatorToken: AccessToken, targetUserId: String, targetPerms: Int): Either[String, AccessToken] = {
    // Verify delegator has ADMIN permission
    if ((delegatorToken.permBits & PermissionFlags.ADMIN) == 0) {
      return Left("Only admins can delegate")
    }

    // CRITICAL CHECK: Ensure delegator cannot escalate beyond their own permissions
    // We compute the effective permission set that can be delegated
    val allowedDelegation = computeAllowedDelegation(delegatorToken.permBits, targetPerms)

    delegationRegistry.put(targetUserId, allowedDelegation)
    Right(AccessToken(targetUserId, delegatorToken.tenantId, allowedDelegation, delegatorToken.expiry))
  }

  // Compute what permissions can actually be delegated
  // Rule: you can only delegate permissions at or below your own level
  private def computeAllowedDelegation(delegatorBits: Int, requestedBits: Int): Int = {
    // Only allow delegating permissions the delegator actually has
    // Direct bitwise AND ensures no escalation is possible
    requestedBits & delegatorBits & 0x0F
  }
}
